INSERT INTO "records" VALUES('record','WTDS-d0868f91-3',16,'{"id": "WTDS-d0868f91-3", "inst": "Amgueddfa Cymru - Museum Wales", "regime": "FOI", "their_ref": "FOI 2026-036", "asked": "2026-10-07", "asks": [{"date": "2026-10-07", "kind": "request", "text": "The requester accepts the Ref 13.2 distinction and asks whether MS 3360/3 contains further identifiers distinguishing which Llandough is meant.", "ref": "1a117581dc9c1a2b"}], "acks": [], "reply": {"date": "2026-10-08", "class": "not held", "text": "The FOI officer states no further recorded information identifying Great House Farm exists within MS 3360/3 beyond what was disclosed.", "ref": "1a11ad2b22443cb9", "exemptions": []}, "status": "not_held", "flags": [], "due": "2026-11-04", "due_basis": "20 working days (FOIA s10 / EIR reg 5(2))", "due_max": null, "next": "Internal review asking where the records went: retention schedule, transfer, disposal record and search description", "next_from": null, "next_by": "2026-12-03", "source": "Gmail correspondence record", "route": "Email", "open": null, "tone": "amber", "links": [{"t": "ask", "href": "/email/reference/1a117581dc9c1a2b/", "d": "2026-10-07"}, {"t": "reply", "href": "/email/reference/1a11ad2b22443cb9/", "d": "2026-10-08"}, {"t": "dartboard", "href": "/dartboard/"}, {"t": "mr", "href": "/research/missing-records/"}], "silent_days": null, "overdue_days": null, "ev": "EV-0297", "source_ids": ["EV-0297", "1a117581dc9c1a2b", "1a11ad2b22443cb9"]}');
