INSERT INTO "records" VALUES('record','WTDS-c68bb0f8-1',130,'{"id": "WTDS-c68bb0f8-1", "inst": "Northern Ireland Office", "regime": "FOI internal review", "their_ref": "26FOI 103; IR/26/16", "asked": "2026-10-21", "asks": [{"date": "2026-10-21", "kind": "chase", "text": "The requester follows up on IR/26/16.", "ref": "1a15f55aead048aa"}], "acks": [], "reply": {"date": "2026-10-26", "class": "not held", "text": "Internal review IR/26/16 of 26FOI 103 completed: the original \"not held\" answer is upheld. Searches were digital only, with the terms \"Great House Farm, House of Williams/Buckler, Llandough\"; pre-1999 Welsh Office paper files went to the National Assembly for Wales (Transfer of Records Order 2004) and later the Welsh Government. Next step offered: ICO complaint.", "ref": "1a1793ba43e8d95b", "exemptions": []}, "status": "not_held", "flags": [], "due": null, "due_basis": "", "due_max": null, "next": "ICO complaint about the review outcome", "next_from": null, "next_by": "2026-12-07", "source": "Gmail correspondence record", "route": "Email", "open": null, "tone": "amber", "links": [{"t": "ask", "href": "/email/reference/1a15f55aead048aa/", "d": "2026-10-21"}, {"t": "reply", "href": "/email/reference/1a1793ba43e8d95b/", "d": "2026-10-26"}, {"t": "dartboard", "href": "/dartboard/"}, {"t": "mr", "href": "/research/missing-records/"}], "silent_days": null, "overdue_days": null, "source_ids": ["1a15f55aead048aa", "1a1793ba43e8d95b"]}');
