INSERT INTO "records" VALUES('record','WTDS-2a274db6-1',138,'{"id": "WTDS-2a274db6-1", "inst": "RCAHMW (Royal Commission)", "regime": "FOI", "their_ref": "RC26-0353, RC26-0368, RC26-0371, RC26-0375", "asked": "2026-09-08", "asks": [{"date": "2026-09-08", "kind": "request", "text": "The requester submits a formal request for 1988 unpublished records and related survey material concerning ironwork found at Great House Farm.", "ref": "1a07ef79c476e63d"}, {"date": "2026-09-15", "kind": "request", "text": "The requester asks the cataloguing team to verify whether an Emergency Recording case is misassigned to Bonvilston instead of Llandough and to relink it.", "ref": "1a0a6bb6d43d5b5f"}, {"date": "2026-09-17", "kind": "request", "text": "Requests confirmation whether the institution was consulted, notified or asked to record Great House Farm before its December 1988 demolition.", "ref": "1a0ad6441e1b82e9"}, {"date": "2026-09-20", "kind": "request", "text": "Sends a brief follow-up message to named staff regarding the Tŷ Mawr/Great House site, with content otherwise unspecified.", "ref": "1a0bda407bdaa9ab"}], "acks": ["2026-09-08", "2026-09-16", "2026-09-17", "2026-09-21"], "reply": {"date": "2026-09-29", "class": "partial", "text": "States no letters or records on the site exist in registered files, cites archive catalogue entries, and quotes a historic-environment description.", "ref": "1a0ed5d3ada10e6b", "exemptions": []}, "status": "partial", "flags": [], "due": "2026-10-06", "due_basis": "20 working days (FOIA s.10 / EIR reg 5(2))", "due_max": null, "next": "Internal review asking for the unanswered parts and a description of the searches made", "next_from": null, "next_by": "2026-11-24", "source": "Gmail correspondence record", "route": "Email", "open": null, "tone": "amber", "links": [{"t": "ask", "href": "/email/reference/1a07ef79c476e63d/", "d": "2026-09-08"}, {"t": "ask", "href": "/email/reference/1a0a6bb6d43d5b5f/", "d": "2026-09-15"}, {"t": "ask", "href": "/email/reference/1a0ad6441e1b82e9/", "d": "2026-09-17"}, {"t": "ask", "href": "/email/reference/1a0bda407bdaa9ab/", "d": "2026-09-20"}, {"t": "reply", "href": "/email/reference/1a0ed5d3ada10e6b/", "d": "2026-09-29"}, {"t": "dartboard", "href": "/dartboard/"}], "silent_days": null, "overdue_days": null, "ev": "EV-0432", "source_ids": ["EV-0432", "1a07ef79c476e63d", "1a0a6bb6d43d5b5f", "1a0ad6441e1b82e9", "1a0bda407bdaa9ab", "1a0ed5d3ada10e6b"]}');
INSERT INTO "records" VALUES('record','WTDS-2a274db6-2',139,'{"id": "WTDS-2a274db6-2", "inst": "RCAHMW (Royal Commission)", "regime": "FOI", "their_ref": "RC26-0353, RC26-0368, RC26-0371, RC26-0375", "asked": "2026-10-10", "asks": [{"date": "2026-10-10", "kind": "chase", "text": "Confirms earlier requests are treated as answered and asks for scans plus confirmation on accession records and catalogue linkage for the emergency-recording case.", "ref": "1a1273a3966769ad"}, {"date": "2026-10-10", "kind": "request", "text": "The requester orders free research-quality scans of three named archive items and asks about order form validity and fee waiver.", "ref": "1a1273a71e6cec27"}], "acks": [], "reply": {"date": "2026-10-13", "class": "fee or clarification demand", "text": "The records team requests a completed order form for three scan items, confirms fee waiver, and states no further information is held beyond the catalogue; clarifies an unrelated archive item.", "ref": "1a135bdc3ab000b2", "exemptions": []}, "status": "clarification", "flags": [], "due": "2026-11-06", "due_basis": "20 working days (FOIA s10 / EIR reg 5(2))", "due_max": null, "next": "Answer the clarification; the 20-working-day clock restarts on the answer", "next_from": null, "next_by": null, "source": "Gmail correspondence record", "route": "Email", "open": null, "tone": "amber", "links": [{"t": "ask", "href": "/email/reference/1a1273a3966769ad/", "d": "2026-10-10"}, {"t": "ask", "href": "/email/reference/1a1273a71e6cec27/", "d": "2026-10-10"}, {"t": "reply", "href": "/email/reference/1a135bdc3ab000b2/", "d": "2026-10-13"}, {"t": "dartboard", "href": "/dartboard/"}], "silent_days": null, "overdue_days": null, "ev": "EV-0432", "source_ids": ["EV-0432", "1a1273a3966769ad", "1a1273a71e6cec27", "1a135bdc3ab000b2"]}');
